    textAlign: "left",
    fontSize: 10,
    fontWeight: 700,
    textTransform: "uppercase",
    letterSpacing: ".05em",
    color: "#94a3b8",
    background: "#f8fafc",
    borderBottom: "1px solid #e2e8f0",
    whiteSpace: "nowrap"
  },
  tr: {
    borderBottom: "1px solid #f1f5f9",
    cursor: "pointer",
    transition: "background .1s"
  },
  td: {
    padding: "10px 12px",
    verticalAlign: "middle"
  },
  pagination: {
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    paddingTop: 16,
    flexWrap: "wrap",
    gap: 10
  },
  pgBtn: {
    minWidth: 32,
    height: 32,
    padding: "0 8px",
    border: "1px solid #e2e8f0",
    borderRadius: 6,
    background: "#fff",
    fontSize: 13,
    cursor: "pointer",
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center"
  },
  pgBtnActive: {
    background: "#2563eb",
    color: "#fff",
    borderColor: "#2563eb"
  }
};

// ── CSS string (animations) ───────────────────────────────────────────────────
const CSS = `
  @keyframes spin     { to { transform: rotate(360deg); } }
  @keyframes slideIn  { from { transform: translateX(100%); } to { transform: translateX(0); } }
  table tbody tr:hover { background: #eff6ff !important; }
  button:disabled { opacity: .4; cursor: default; }
  input:focus, select:focus { border-color: #2563eb !important; outline: none; }
`;
var _c, _c2, _c3, _c4, _c5, _c6, _c7, _c8;
$RefreshReg$(_c, "Badge");
$RefreshReg$(_c2, "Spinner");
$RefreshReg$(_c3, "EmptyState");
$RefreshReg$(_c4, "DetailPanel");
$RefreshReg$(_c5, "Section");
$RefreshReg$(_c6, "Row");
$RefreshReg$(_c7, "AuditLogSearch");
$RefreshReg$(_c8, "FilterField");

sourcesContent:
/**
 * AuditLogSearch.jsx
 * ------------------
 * Audit Log History Search Page for VMS
 *
 * Features:
 *  - Search by: date, date range, time range, action, entity,
 *               user ID, entity ID, IP address
 *  - Quick filters: Today / Yesterday / Last 7d / Last 30d / All
 *  - Sort: Newest first / Oldest first
 *  - Pagination (50 per page)
 *  - Click row → full detail slide-in panel
 *  - Color-coded action badges
 *
 * Usage:
 *   import AuditLogSearch from './pages/AuditLogSearch';
 *   // Add to your router:
 *   <Route path="/audit-logs" element={<AuditLogSearch />} />
 *
 * Expects:
 *   - localStorage key "vms_token" containing the Bearer JWT
 *   - Backend running at VITE_API_BASE (default http://localhost:8000/api)
 */

import { useState, useEffect, useCallback, useRef } from "react";

// ── Config ────────────────────────────────────────────────────────────────────
const API_BASE  = import.meta.env?.VITE_API_BASE ?? "http://localhost:8000/api";
const PAGE_SIZE = 50;

// ── Helpers ───────────────────────────────────────────────────────────────────
const getToken = () => localStorage.getItem("vms_token") ?? "";

const apiFetch = (url, token) =>
  fetch(url, { headers: { Authorization: `Bearer ${token}` } });

const fmtDate = (iso) =>
  iso
    ? new Date(iso).toLocaleDateString("en-IN", {
        day: "2-digit", month: "short", year: "numeric",
      })
    : "—";

const fmtTime = (iso) =>
  iso
    ? new Date(iso).toLocaleTimeString("en-IN", {
        hour: "2-digit", minute: "2-digit", second: "2-digit",
      })
    : "—";

const fmtDateTime = (iso) =>
  iso ? `${fmtDate(iso)}  ${fmtTime(iso)}` : "—";

const todayStr = () => new Date().toISOString().split("T")[0];
const daysAgoStr = (n) => {
  const d = new Date();
  d.setDate(d.getDate() - n);
  return d.toISOString().split("T")[0];
};

// Action color map
const ACTION_COLORS = {
  login:      { bg: "#dbeafe", text: "#1e40af" },
  logout:     { bg: "#f3f4f6", text: "#374151" },
  create:     { bg: "#dcfce7", text: "#15803d" },
  update:     { bg: "#fef9c3", text: "#854d0e" },
  delete:     { bg: "#fee2e2", text: "#b91c1c" },
  scan:       { bg: "#ede9fe", text: "#6d28d9" },
  check_in:   { bg: "#d1fae5", text: "#065f46" },
  check_out:  { bg: "#e0f2fe", text: "#0369a1" },
  default:    { bg: "#f1f5f9", text: "#475569" },
};

const actionColor = (action = "") => {
  const key = Object.keys(ACTION_COLORS).find((k) =>
    action.toLowerCase().includes(k)
  );
  return ACTION_COLORS[key] ?? ACTION_COLORS.default;
};

// ── Sub-components ────────────────────────────────────────────────────────────

function Badge({ label }) {
  const { bg, text } = actionColor(label);
  return (
    <span style={{
      background: bg, color: text,
      padding: "2px 10px", borderRadius: 20,
      fontSize: 11, fontWeight: 600, whiteSpace: "nowrap",
    }}>
      {label || "—"}
    </span>
  );
}

function Spinner() {
  return (
    <div style={{ textAlign: "center", padding: 48, color: "#94a3b8" }}>
      <div style={{
        width: 32, height: 32, margin: "0 auto 12px",
        border: "3px solid #e2e8f0", borderTopColor: "#2563eb",
        borderRadius: "50%", animation: "spin .7s linear infinite",
      }} />
      Searching audit logs…
    </div>
  );
}

function EmptyState({ msg }) {
  return (
    <div style={{ textAlign: "center", padding: 56, color: "#94a3b8" }}>
      <svg width="44" height="44" fill="none" stroke="currentColor" strokeWidth="1.5"
        viewBox="0 0 24 24" style={{ display: "block", margin: "0 auto 14px", opacity: .5 }}>
        <path d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586
          a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/>
      </svg>
      {msg ?? "No audit logs found for the selected filters."}
    </div>
  );
}

// ── Detail Panel ──────────────────────────────────────────────────────────────
function DetailPanel({ log, onClose }) {
  if (!log) return null;
  let parsedDetails = null;
  try { parsedDetails = JSON.parse(log.details); } catch { parsedDetails = null; }

  return (
    <div style={{
      position: "fixed", inset: 0, zIndex: 200,
      display: "flex", justifyContent: "flex-end",
    }}>
      {/* backdrop */}
      <div onClick={onClose} style={{
        position: "absolute", inset: 0, background: "rgba(0,0,0,.35)",
      }} />

      {/* panel */}
      <div style={{
        position: "relative", zIndex: 1,
        width: "min(480px, 95vw)", background: "#fff",
        boxShadow: "-4px 0 24px rgba(0,0,0,.15)",
        display: "flex", flexDirection: "column",
        animation: "slideIn .2s ease",
      }}>
        {/* header */}
        <div style={{
          padding: "16px 20px", borderBottom: "1px solid #e2e8f0",
          display: "flex", alignItems: "center", justifyContent: "space-between",
        }}>
          <div>
            <div style={{ fontSize: 15, fontWeight: 700 }}>Audit Log #{log.id}</div>
            <div style={{ fontSize: 12, color: "#94a3b8", marginTop: 2 }}>
              {fmtDateTime(log.created_at)}
            </div>
          </div>
          <button onClick={onClose} style={{
            width: 32, height: 32, borderRadius: 6, border: "none",
            background: "#f1f5f9", cursor: "pointer", fontSize: 16,
            display: "flex", alignItems: "center", justifyContent: "center",
          }}>✕</button>
        </div>

        {/* body */}
        <div style={{ padding: 20, overflowY: "auto", flex: 1 }}>

          {/* Action + Entity */}
          <Section title="Action">
            <Row label="Action"><Badge label={log.action} /></Row>
            <Row label="Entity">{log.entity ?? "—"}</Row>
            <Row label="Entity ID">{log.entity_id ?? "—"}</Row>
          </Section>

          {/* Who */}
          <Section title="Performed By">
            <Row label="User ID">{log.user_id ?? "System"}</Row>
            <Row label="IP Address">{log.ip_address ?? "—"}</Row>
          </Section>

          {/* When */}
          <Section title="Timestamp">
            <Row label="Date">{fmtDate(log.created_at)}</Row>
            <Row label="Time">{fmtTime(log.created_at)}</Row>
          </Section>

          {/* Details */}
          <Section title="Details">
            {parsedDetails ? (
              <div style={{
                background: "#f8fafc", borderRadius: 6, padding: 12,
                fontSize: 12, fontFamily: "monospace",
                whiteSpace: "pre-wrap", wordBreak: "break-all",
                border: "1px solid #e2e8f0", maxHeight: 240, overflowY: "auto",
              }}>
                {JSON.stringify(parsedDetails, null, 2)}
              </div>
            ) : (
              <div style={{
                fontSize: 13, color: "#475569",
                background: "#f8fafc", padding: 10, borderRadius: 6,
                border: "1px solid #e2e8f0",
              }}>
                {log.details ?? "No details recorded."}
              </div>
            )}
          </Section>
        </div>
      </div>
    </div>
  );
}

function Section({ title, children }) {
  return (
    <div style={{ marginBottom: 20 }}>
      <div style={{
        fontSize: 10, fontWeight: 700, textTransform: "uppercase",
        letterSpacing: ".08em", color: "#94a3b8", marginBottom: 10,
      }}>{title}</div>
      <div style={{
        background: "#f8fafc", borderRadius: 8,
        border: "1px solid #e2e8f0", overflow: "hidden",
      }}>{children}</div>
    </div>
  );
}

function Row({ label, children }) {
  return (
    <div style={{
      display: "flex", alignItems: "center", justifyContent: "space-between",
      padding: "9px 14px", borderBottom: "1px solid #e2e8f0",
      fontSize: 13,
    }}>
      <span style={{ color: "#94a3b8", fontWeight: 500, flexShrink: 0, marginRight: 12 }}>
        {label}
      </span>
      <span style={{ color: "#1e293b", fontWeight: 500, textAlign: "right" }}>
        {children}
      </span>
    </div>
  );
}

// ── Main Page ─────────────────────────────────────────────────────────────────
export default function AuditLogSearch() {
  // filters
  const [filters, setFilters] = useState({
    action:     "",
    entity:     "",
    entity_id:  "",
    user_id:    "",
    ip_address: "",
    date:       todayStr(),
    date_from:  "",
    date_to:    "",
    time_from:  "",
    time_to:    "",
    last_n_days: "",
    sort_order: "desc",
  });

  const [activeQuick, setActiveQuick] = useState("today");

  // results
  const [logs,    setLogs]    = useState([]);
  const [total,   setTotal]   = useState(0);
  const [skip,    setSkip]    = useState(0);
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState("");

  // detail panel
  const [selected, setSelected] = useState(null);

  // debounce ref
  const debounceRef = useRef(null);

  // ── Fetch ───────────────────────────────────────────────────────────────
  const fetchLogs = useCallback(async (overrideSkip) => {
    setLoading(true);
    setError("");
    const currentSkip = overrideSkip ?? skip;

    const p = new URLSearchParams();
    if (filters.action)     p.set("action",      filters.action.trim());
    if (filters.entity)     p.set("entity",      filters.entity.trim());
    if (filters.entity_id)  p.set("entity_id",   filters.entity_id);
    if (filters.user_id)    p.set("user_id",      filters.user_id);
    if (filters.ip_address) p.set("ip_address",  filters.ip_address.trim());
    if (filters.time_from)  p.set("time_from",   filters.time_from);
    if (filters.time_to)    p.set("time_to",     filters.time_to);
    p.set("sort_order", filters.sort_order);
    p.set("skip",  currentSkip);
    p.set("limit", PAGE_SIZE);

    if (filters.last_n_days) {
      p.set("last_n_days", filters.last_n_days);
    } else if (filters.date) {
      p.set("date", filters.date);
    } else {
      if (filters.date_from) p.set("date_from", filters.date_from);
      if (filters.date_to)   p.set("date_to",   filters.date_to);
    }

    try {
      const res  = await apiFetch(`${API_BASE}/admin/audit-logs/search?${p}`, getToken());
      if (res.status === 401) { setError("Session expired — please login again."); return; }
      if (!res.ok) { const e = await res.json(); setError(e.detail ?? "Server error"); return; }
      const data = await res.json();
      setLogs(data.results);
      setTotal(data.total);
    } catch {
      setError("Cannot reach server. Make sure backend is running on localhost:8000");
    } finally {
      setLoading(false);
    }
  }, [filters, skip]);

  // ── Auto-search on filter change (debounced) ───────────────────────────
  useEffect(() => {
    clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => {
      setSkip(0);
      fetchLogs(0);
    }, 400);
    return () => clearTimeout(debounceRef.current);
  }, [filters]);                  // eslint-disable-line

  // ── Quick filter handler ───────────────────────────────────────────────
  const applyQuick = (mode) => {
    setActiveQuick(mode);
    if (mode === "today") {
      setFilters(f => ({ ...f, date: todayStr(), date_from: "", date_to: "", last_n_days: "" }));
    } else if (mode === "yesterday") {
      setFilters(f => ({ ...f, date: daysAgoStr(1), date_from: "", date_to: "", last_n_days: "" }));
    } else if (mode === "7d") {
      setFilters(f => ({ ...f, date: "", date_from: "", date_to: "", last_n_days: "7" }));
    } else if (mode === "30d") {
      setFilters(f => ({ ...f, date: "", date_from: "", date_to: "", last_n_days: "30" }));
    } else if (mode === "all") {
      setFilters(f => ({ ...f, date: "", date_from: "", date_to: "", last_n_days: "" }));
    }
  };

  const setF = (key) => (e) => {
    setActiveQuick("");
    setFilters(f => ({ ...f, [key]: e.target.value }));
  };

  const clearAll = () => {
    setActiveQuick("today");
    setFilters({
      action: "", entity: "", entity_id: "", user_id: "",
      ip_address: "", date: todayStr(), date_from: "", date_to: "",
      time_from: "", time_to: "", last_n_days: "", sort_order: "desc",
    });
  };

  // ── Pagination ─────────────────────────────────────────────────────────
  const totalPages  = Math.ceil(total / PAGE_SIZE);
  const currentPage = Math.floor(skip / PAGE_SIZE);

  const goTo = (page) => {
    const s = page * PAGE_SIZE;
    setSkip(s);
    fetchLogs(s);
  };

  // ── Inline styles ──────────────────────────────────────────────────────
  const s = styles;

  return (
    <>
      <style>{CSS}</style>

      <div style={s.page}>

        {/* ── Page header ── */}
        <div style={s.pageHeader}>
          <div style={s.pageTitle}>
            <svg width="20" height="20" fill="none" stroke="#2563eb" strokeWidth="2"
              viewBox="0 0 24 24">
              <path d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586
                a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/>
            </svg>
            Audit Log History
          </div>
          <div style={{ fontSize: 13, color: "#94a3b8" }}>
            {total > 0 && `${total.toLocaleString()} record${total !== 1 ? "s" : ""} found`}
          </div>
        </div>

        {/* ── Filter card ── */}
        <div style={s.card}>
          <div style={s.cardTitle}>Search & Filter</div>

          {/* Quick buttons */}
          <div style={{ marginBottom: 16 }}>
            <div style={s.filterLabel}>Quick Select</div>
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginTop: 6 }}>
              {[
                { key: "today",     label: "Today" },
                { key: "yesterday", label: "Yesterday" },
                { key: "7d",        label: "Last 7 Days" },
                { key: "30d",       label: "Last 30 Days" },
                { key: "all",       label: "All Time" },
              ].map(({ key, label }) => (
                <button key={key}
                  onClick={() => applyQuick(key)}
                  style={{
                    ...s.qbtn,
                    ...(activeQuick === key ? s.qbtnActive : {}),
                  }}>
                  {label}
                </button>
              ))}
            </div>
          </div>

          {/* Filter grid */}
          <div style={s.filterGrid}>

            {/* Row 1 — Action / Entity / Entity ID / User ID */}
            <FilterField label="Action" hint="e.g. login, create, delete">
              <input style={s.input} value={filters.action}
                placeholder="login / create / delete…"
                onChange={setF("action")} />
            </FilterField>

            <FilterField label="Entity Type" hint="e.g. visit, user, visitor">
              <select style={s.input} value={filters.entity} onChange={setF("entity")}>
                <option value="">All Entities</option>
                <option value="visit">visit</option>
                <option value="visitor">visitor</option>
                <option value="user">user</option>
                <option value="branch">branch</option>
              </select>
            </FilterField>

            <FilterField label="Entity ID">
              <input style={s.input} type="number" min="1"
                value={filters.entity_id}
                placeholder="e.g. 42"
                onChange={setF("entity_id")} />
            </FilterField>

            <FilterField label="User ID">
              <input style={s.input} type="number" min="1"
                value={filters.user_id}
                placeholder="e.g. 3"
                onChange={setF("user_id")} />
            </FilterField>

            {/* Row 2 — Dates */}
            <FilterField label="Exact Date">
              <input style={s.input} type="date"
                value={filters.date}
                onChange={(e) => {
                  setActiveQuick("");
                  setFilters(f => ({ ...f, date: e.target.value, date_from: "", date_to: "", last_n_days: "" }));
                }} />
            </FilterField>

            <FilterField label="Date From">
              <input style={s.input} type="date"
                value={filters.date_from}
                onChange={(e) => {
                  setActiveQuick("");
                  setFilters(f => ({ ...f, date_from: e.target.value, date: "", last_n_days: "" }));
                }} />
            </FilterField>

            <FilterField label="Date To">
              <input style={s.input} type="date"
                value={filters.date_to}
                onChange={(e) => {
                  setActiveQuick("");
                  setFilters(f => ({ ...f, date_to: e.target.value, date: "", last_n_days: "" }));
                }} />
            </FilterField>

            {/* Row 3 — Time + IP + Sort */}
            <FilterField label="Time From (HH:MM)">
              <input style={s.input} type="time"
                value={filters.time_from} onChange={setF("time_from")} />
            </FilterField>

            <FilterField label="Time To (HH:MM)">
              <input style={s.input} type="time"
                value={filters.time_to} onChange={setF("time_to")} />
            </FilterField>

            <FilterField label="IP Address">
              <input style={s.input}
                value={filters.ip_address}
                placeholder="e.g. 192.168"
                onChange={setF("ip_address")} />
            </FilterField>

            <FilterField label="Sort Order">
              <select style={s.input} value={filters.sort_order} onChange={setF("sort_order")}>
                <option value="desc">Newest First</option>
                <option value="asc">Oldest First</option>
              </select>
            </FilterField>

          </div>

          <div style={{ display: "flex", gap: 10, marginTop: 4 }}>
            <button style={s.btnPrimary} onClick={() => { setSkip(0); fetchLogs(0); }}>
              <svg width="14" height="14" fill="none" stroke="currentColor" strokeWidth="2.5"
                viewBox="0 0 24 24" style={{ flexShrink: 0 }}>
                <circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/>
              </svg>
              Search
            </button>
            <button style={s.btnSecondary} onClick={clearAll}>Clear Filters</button>
          </div>
        </div>

        {/* ── Error ── */}
        {error && (
          <div style={s.errorBox}>{error}</div>
        )}

        {/* ── Results ── */}
        <div style={s.card}>
          {loading ? (
            <Spinner />
          ) : logs.length === 0 ? (
            <EmptyState />
          ) : (
            <>
              <div style={{ overflowX: "auto" }}>
                <table style={s.table}>
                  <thead>
                    <tr>
                      {["ID","Date","Time","Action","Entity","Entity ID","User ID","IP Address",""].map(h => (
                        <th key={h} style={s.th}>{h}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {logs.map((log) => (
                      <tr key={log.id}
                        onClick={() => setSelected(log)}
                        style={s.tr}>
                        <td style={{ ...s.td, color: "#94a3b8", fontSize: 11 }}>#{log.id}</td>
                        <td style={s.td}>{fmtDate(log.created_at)}</td>
                        <td style={{ ...s.td, fontFamily: "monospace", fontSize: 12 }}>
                          {fmtTime(log.created_at)}
                        </td>
                        <td style={s.td}><Badge label={log.action} /></td>
                        <td style={{ ...s.td, color: "#475569" }}>{log.entity ?? "—"}</td>
                        <td style={{ ...s.td, color: "#475569" }}>{log.entity_id ?? "—"}</td>
                        <td style={{ ...s.td, color: "#475569" }}>{log.user_id ?? "System"}</td>
                        <td style={{ ...s.td, fontSize: 12, fontFamily: "monospace", color: "#475569" }}>
                          {log.ip_address ?? "—"}
                        </td>
                        <td style={s.td}>
                          <button
                            onClick={(e) => { e.stopPropagation(); setSelected(log); }}
                            style={s.btnDetail}>
                            Detail
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              {/* Pagination */}
              {totalPages > 1 && (
                <div style={s.pagination}>
                  <span style={{ fontSize: 13, color: "#94a3b8" }}>
                    Showing {skip + 1}–{Math.min(skip + PAGE_SIZE, total)} of {total.toLocaleString()}
                  </span>
                  <div style={{ display: "flex", gap: 6 }}>
                    <button style={s.pgBtn} disabled={currentPage === 0}
                      onClick={() => goTo(currentPage - 1)}>‹</button>
                    {Array.from({ length: totalPages }, (_, i) => {
                      if (totalPages > 7 && Math.abs(i - currentPage) > 2
                          && i !== 0 && i !== totalPages - 1) {
                        return (i === 1 || i === totalPages - 2)
                          ? <span key={i} style={s.pgBtn}>…</span>
                          : null;
                      }
                      return (
                        <button key={i} style={{
                          ...s.pgBtn,
                          ...(i === currentPage ? s.pgBtnActive : {}),
                        }} onClick={() => goTo(i)}>{i + 1}</button>
                      );
                    })}
                    <button style={s.pgBtn} disabled={currentPage >= totalPages - 1}
                      onClick={() => goTo(currentPage + 1)}>›</button>
                  </div>
                </div>
              )}
            </>
          )}
        </div>

      </div>

      {/* ── Detail side panel ── */}
      {selected && (
        <DetailPanel log={selected} onClose={() => setSelected(null)} />
      )}
    </>
  );
}

// ── FilterField wrapper ────────────────────────────────────────────────────────
function FilterField({ label, hint, children }) {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
      <label style={{ fontSize: 11, fontWeight: 600, color: "#64748b",
        textTransform: "uppercase", letterSpacing: ".04em" }}>
        {label}
      </label>
      {children}
      {hint && <span style={{ fontSize: 10, color: "#94a3b8" }}>{hint}</span>}
    </div>
  );
}

